 24	@Service
 25	@RequiredArgsConstructor
 26	public class PedidoService {
 27	    private final PedidoRepository pedidoRepository;
 28	    private final ClienteRepository clienteRepository;
 29	    private final AvisoRepository avisoRepository;
 30	    private final ProdutoRepository produtoRepository;
 31	    private final CalculoService calculoService;
 32	    private final ObjectMapper objectMapper;
 33	
 34	    @Transactional
 35	    public RespostaPedido registrarPedido(DadosCompra dados) {
 36	        var resumo = calculoService.calcularResumo(dados);
 37	
 38	        var cliente = clienteRepository.findById(dados.getCliente().getCpf())
 39	            .orElseGet(() -> criarCliente(dados));
 40	
 41	        var pedido = Pedido.builder()
 42	            .cpfCliente(dados.getCliente().getCpf())
 43	            .situacao(Pedido.SituacaoPedido.AGUARDANDO_PAGAMENTO)
 44	            .criadoEm(Instant.now())
 45	            .resumoJson(serializarResumo(resumo))
 46	            .build();
 47	
 48	        pedido = pedidoRepository.save(pedido);
 49	
 50	        for (var item : dados.getItens()) {
 51	            var itemPedido = ItemPedido.builder()
 52	                .pedidoId(pedido.getId())
 53	                .sku(item.getSku())
 54	                .quantidade(item.getQuantidade())
 55	                .build();
 56	            pedido.getItens().add(itemPedido);
 57	        }
 58	
 59	        pedidoRepository.save(pedido);
 60	
 61	        return mapearPedido(pedido, resumo);
 62	    }
 63	
 64	    @Transactional
 65	    public RespostaPedido obterPedido(Long id) {
 66	        var pedido = pedidoRepository.findById(id)
 67	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
 68	
 69	        var resumo = desserializarResumo(pedido.getResumoJson());
 70	        return mapearPedido(pedido, resumo);
 71	    }
 72	
 73	    @Transactional
 74	    public RespostaPedido registrarPagamento(Long id, RequisicaoPagamento requisicao) {
 75	        var pedido = pedidoRepository.findById(id)
 76	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
 77	
 78	        if (pedido.getSituacao() != Pedido.SituacaoPedido.AGUARDANDO_PAGAMENTO) {
 79	            throw ErroNegocio.operacaoNaoPermitida();
 80	        }
 81	
 82	        var agora = Instant.now();
 83	        var diferenca = ChronoUnit.HOURS.between(pedido.getCriadoEm(), requisicao.getPagoEm());
 84	        if (diferenca > 48) {
 85	            pedido.setSituacao(Pedido.SituacaoPedido.CANCELADO);
 86	            pedidoRepository.save(pedido);
 87	            criarAviso(pedido, Aviso.TipoAviso.PEDIDO_CANCELADO);
 88	            throw ErroNegocio.pedidoExpirado();
 89	        }
 90	
 91	        if (pedido.getIdTransacao() != null && pedido.getIdTransacao().equals(requisicao.getIdTransacao())) {
 92	            var resumo = desserializarResumo(pedido.getResumoJson());
 93	            return mapearPedido(pedido, resumo);
 94	        }
 95	
 96	        if (pedido.getIdTransacao() == null) {
 97	            validarEstoque(pedido);
 98	
 99	            pedido.setSituacao(Pedido.SituacaoPedido.PAGO);
100	            pedido.setIdTransacao(requisicao.getIdTransacao());
101	            pedido.setPagoEm(requisicao.getPagoEm());
102	            pedidoRepository.save(pedido);
103	
104	            baixarEstoque(pedido);
105	            adicionarCreditoClube(pedido);
106	            criarAviso(pedido, Aviso.TipoAviso.PAGAMENTO_APROVADO);
107	        }
108	
109	        var resumo = desserializarResumo(pedido.getResumoJson());
110	        return mapearPedido(pedido, resumo);
111	    }
112	
113	    @Transactional
114	    public RespostaPedido registrarEnvio(Long id, RequisicaoEnvio requisicao) {
115	        var pedido = pedidoRepository.findById(id)
116	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
117	
118	        if (pedido.getSituacao() != Pedido.SituacaoPedido.PAGO) {
119	            throw ErroNegocio.operacaoNaoPermitida();
120	        }
121	
122	        pedido.setSituacao(Pedido.SituacaoPedido.ENVIADO);
123	        pedido.setCodigoRastreio(requisicao.getCodigoRastreio());
124	        pedidoRepository.save(pedido);
125	
126	        criarAviso(pedido, Aviso.TipoAviso.PEDIDO_ENVIADO);
127	
128	        var resumo = desserializarResumo(pedido.getResumoJson());
129	        return mapearPedido(pedido, resumo);
130	    }
131	
132	    @Transactional
133	    public RespostaPedido registrarEntrega(Long id) {
134	        var pedido = pedidoRepository.findById(id)
135	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
136	
137	        if (pedido.getSituacao() != Pedido.SituacaoPedido.ENVIADO) {
138	            throw ErroNegocio.operacaoNaoPermitida();
139	        }
140	
141	        pedido.setSituacao(Pedido.SituacaoPedido.ENTREGUE);
142	        pedidoRepository.save(pedido);
143	
144	        var resumo = desserializarResumo(pedido.getResumoJson());
145	        return mapearPedido(pedido, resumo);
146	    }
147	
148	    @Transactional
149	    public RespostaPedido cancelarPedido(Long id) {
150	        var pedido = pedidoRepository.findById(id)
151	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
152	
153	        if (pedido.getSituacao() == Pedido.SituacaoPedido.ENVIADO ||
154	            pedido.getSituacao() == Pedido.SituacaoPedido.ENTREGUE) {
155	            throw ErroNegocio.operacaoNaoPermitida();
156	        }
157	
158	        if (pedido.getSituacao() == Pedido.SituacaoPedido.PAGO) {
159	            devolverEstoque(pedido);
160	            removerCreditoClube(pedido);
161	        }
162	
163	        pedido.setSituacao(Pedido.SituacaoPedido.CANCELADO);
164	        pedidoRepository.save(pedido);
165	
166	        criarAviso(pedido, Aviso.TipoAviso.PEDIDO_CANCELADO);
167	
168	        var resumo = desserializarResumo(pedido.getResumoJson());
169	        return mapearPedido(pedido, resumo);
170	    }
171	
172	    private Cliente criarCliente(DadosCompra dados) {
173	        var cliente = Cliente.builder()
174	            .cpf(dados.getCliente().getCpf())
175	            .email(dados.getCliente().getEmail())
176	            .saldoCredito(BigDecimal.ZERO)
177	            .criadoEm(Instant.now())
178	            .build();
179	        return clienteRepository.save(cliente);
180	    }
181	
182	    private void validarEstoque(Pedido pedido) {
183	        for (var item : pedido.getItens()) {
184	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
185	            if (produto.getEstoque() < item.getQuantidade()) {
186	                pedido.setSituacao(Pedido.SituacaoPedido.CANCELADO);
187	                pedidoRepository.save(pedido);
188	                criarAviso(pedido, Aviso.TipoAviso.PEDIDO_CANCELADO);
189	                throw ErroNegocio.estoqueInsuficiente(item.getSku());
190	            }
191	        }
192	    }
193	
194	    private void baixarEstoque(Pedido pedido) {
195	        for (var item : pedido.getItens()) {
196	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
197	            produto.setEstoque(produto.getEstoque() - item.getQuantidade());
198	            produtoRepository.save(produto);
199	        }
200	    }
201	
202	    private void devolverEstoque(Pedido pedido) {
203	        for (var item : pedido.getItens()) {
204	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
205	            produto.setEstoque(produto.getEstoque() + item.getQuantidade());
206	            produtoRepository.save(produto);
207	        }
208	    }
209	
210	    private void adicionarCreditoClube(Pedido pedido) {
211	        var cliente = clienteRepository.findById(pedido.getCpfCliente()).orElseThrow();
212	        var resumo = desserializarResumo(pedido.getResumoJson());
213	        var novoSaldo = cliente.getSaldoCredito().add(resumo.getCreditoProximaCompra());
214	        cliente.setSaldoCredito(ArredondamentoUtil.arredondar(novoSaldo));
215	        clienteRepository.save(cliente);
216	    }
217	
218	    private void removerCreditoClube(Pedido pedido) {
219	        var cliente = clienteRepository.findById(pedido.getCpfCliente()).orElseThrow();
220	        var resumo = desserializarResumo(pedido.getResumoJson());
221	        var novoSaldo = cliente.getSaldoCredito().subtract(resumo.getCreditoProximaCompra());
222	        if (novoSaldo.signum() < 0) {
223	            novoSaldo = BigDecimal.ZERO;
224	        }
225	        cliente.setSaldoCredito(ArredondamentoUtil.arredondar(novoSaldo));
226	        clienteRepository.save(cliente);
227	    }
228	
229	    private void criarAviso(Pedido pedido, Aviso.TipoAviso tipo) {
230	        var aviso = Aviso.builder()
231	            .cpfCliente(pedido.getCpfCliente())
232	            .tipo(tipo)
233	            .pedidoId(pedido.getId())
234	            .situacao(Aviso.SituacaoAviso.NOVO)
235	            .criadoEm(Instant.now())
236	            .build();
237	        avisoRepository.save(aviso);
238	    }
239	
240	    private String serializarResumo(Resumo resumo) {
241	        try {
242	            return objectMapper.writeValueAsString(resumo);
243	        } catch (Exception e) {
244	            throw new RuntimeException("Erro ao serializar resumo", e);
245	        }
246	    }
247	
248	    private Resumo desserializarResumo(String resumoJson) {
249	        try {
250	            return objectMapper.readValue(resumoJson, Resumo.class);
251	        } catch (Exception e) {
252	            throw new RuntimeException("Erro ao desserializar resumo", e);
253	        }
254	    }
255	
256	    private RespostaPedido mapearPedido(Pedido pedido, Resumo resumo) {
257	        return RespostaPedido.builder()
258	            .id(pedido.getId())
259	            .situacao(pedido.getSituacao().name())
260	            .criadoEm(pedido.getCriadoEm())
261	            .resumo(resumo)
262	            .itens(pedido.getItens().stream()
263	                .map(i -> new RespostaPedido.Item(i.getSku(), i.getQuantidade()))
264	                .collect(Collectors.toList()))
265	            .codigoRastreio(pedido.getCodigoRastreio() != null ? pedido.getCodigoRastreio() : "")
266	            .build();
267	    }
268	}
